INSERT INTO saunas (id, slug, name, description, prefecture, area, address, lat, lng, price_min, price_max, price_note, capacity_min, capacity_max, temp_min, temp_max, business_hours, closed_note, supports_day_trip, supports_lodging, parking_note, reservation_url, official_url, phone, popularity_score) VALUES ('00000000-0000-4000-a000-733031000000', 'okutama-kawabe-sauna', '奥多摩 川辺サウナ', '多摩川の河原に直接テントを張るサウナ。水深のある淵に飛び込める区画があり、夏は流れの中で体を冷やせる。', '東京都', '奥多摩町', '東京都西多摩郡奥多摩町（架空）', 35.809, 139.0966, 4800, 7200, null, 1, 6, 85, 100, '{"mon":{"open":"09:00","close":"18:00"},"tue":null,"wed":null,"thu":{"open":"09:00","close":"18:00"},"fri":{"open":"09:00","close":"18:00"},"sat":{"open":"09:00","close":"18:00"},"sun":{"open":"09:00","close":"18:00"},"note":"増水時は休業"}'::jsonb, null, true, false, '河原沿いに5台', 'https://example.com/okutama-kawabe/reserve', 'https://example.com/okutama-kawabe', null, 0.82);
INSERT INTO saunas (id, slug, name, description, prefecture, area, address, lat, lng, price_min, price_max, price_note, capacity_min, capacity_max, temp_min, temp_max, business_hours, closed_note, supports_day_trip, supports_lodging, parking_note, reservation_url, official_url, phone, popularity_score) VALUES ('00000000-0000-4000-a000-733032000000', 'hinohara-mori-no-koya', '檜原 森の小屋', '杉林に囲まれた1組限定の小屋サウナ。沢の水を引いた樽で冷やし、ハンモックで森を眺めて休む。', '東京都', '檜原村', '東京都西多摩郡檜原村（架空）', 35.7397, 139.1497, 12000, 18000, '1棟あたり（最大4名）', 1, 4, 90, 105, '{"mon":{"open":"10:00","close":"21:00"},"tue":{"open":"10:00","close":"21:00"},"wed":{"open":"10:00","close":"21:00"},"thu":{"open":"10:00","close":"21:00"},"fri":{"open":"10:00","close":"21:00"},"sat":{"open":"10:00","close":"21:00"},"sun":{"open":"10:00","close":"21:00"},"note":null}'::jsonb, null, true, false, '3台', 'https://example.com/hinohara-mori/reserve', 'https://example.com/hinohara-mori', null, 0.74);
INSERT INTO saunas (id, slug, name, description, prefecture, area, address, lat, lng, price_min, price_max, price_note, capacity_min, capacity_max, temp_min, temp_max, business_hours, closed_note, supports_day_trip, supports_lodging, parking_note, reservation_url, official_url, phone, popularity_score) VALUES ('00000000-0000-4000-a000-733231000000', 'tamagawa-kasenshiki-sauna', '多摩川 河川敷サウナ', '都心から電車で40分の河川敷。浅瀬に膝まで浸かって冷やす。手軽さを優先した価格設定。', '東京都', '稲城市', '東京都稲城市（架空）', 35.6379, 139.5046, 3200, 4200, null, 1, 8, 80, 92, '{"mon":{"open":"10:00","close":"20:00"},"tue":{"open":"10:00","close":"20:00"},"wed":{"open":"10:00","close":"20:00"},"thu":{"open":"10:00","close":"20:00"},"fri":{"open":"10:00","close":"20:00"},"sat":{"open":"10:00","close":"20:00"},"sun":{"open":"10:00","close":"20:00"},"note":"増水時は休業"}'::jsonb, null, true, false, '3台（河川敷駐車場）', 'https://example.com/tamagawa-kasenshiki/reserve', 'https://example.com/tamagawa-kasenshiki', null, 0.58);
INSERT INTO saunas (id, slug, name, description, prefecture, area, address, lat, lng, price_min, price_max, price_note, capacity_min, capacity_max, temp_min, temp_max, business_hours, closed_note, supports_day_trip, supports_lodging, parking_note, reservation_url, official_url, phone, popularity_score) VALUES ('00000000-0000-4000-a000-733033000000', 'hakone-tenku-roten', '箱根 天空露天サウナ', '斜面に張り出したデッキから山並みを見下ろす露天サウナ。夕方は雲海が出ることがある。', '神奈川県', '箱根町', '神奈川県足柄下郡箱根町（架空）', 35.2324, 139.1069, 6500, 9800, null, 2, 10, 80, 95, '{"mon":{"open":"11:00","close":"22:00"},"tue":{"open":"11:00","close":"22:00"},"wed":{"open":"11:00","close":"22:00"},"thu":{"open":"11:00","close":"22:00"},"fri":{"open":"11:00","close":"22:00"},"sat":{"open":"11:00","close":"22:00"},"sun":{"open":"11:00","close":"22:00"},"note":null}'::jsonb, null, true, true, '20台', 'https://example.com/hakone-tenku/reserve', 'https://example.com/hakone-tenku', null, 0.91);
INSERT INTO saunas (id, slug, name, description, prefecture, area, address, lat, lng, price_min, price_max, price_note, capacity_min, capacity_max, temp_min, temp_max, business_hours, closed_note, supports_day_trip, supports_lodging, parking_note, reservation_url, official_url, phone, popularity_score) VALUES ('00000000-0000-4000-a000-733034000000', 'miura-umibe-barrel', '三浦 海辺バレル', '砂浜に据えたバレルサウナ。目の前の海に入って冷やせる。冬は波が高い日が多い。', '神奈川県', '三浦市', '神奈川県三浦市（架空）', 35.1667, 139.65, 5200, 7800, null, 1, 5, 85, 95, '{"mon":{"open":"09:00","close":"19:00"},"tue":{"open":"09:00","close":"19:00"},"wed":null,"thu":{"open":"09:00","close":"19:00"},"fri":{"open":"09:00","close":"19:00"},"sat":{"open":"09:00","close":"19:00"},"sun":{"open":"09:00","close":"19:00"},"note":"荒天時は中止"}'::jsonb, null, true, false, '海岸駐車場を利用（有料）', 'https://example.com/miura-barrel/reserve', 'https://example.com/miura-barrel', null, 0.78);
