INSERT INTO saunas (id, slug, name, description, prefecture, area, address, lat, lng, price_min, price_max, price_note, capacity_min, capacity_max, temp_min, temp_max, business_hours, closed_note, supports_day_trip, supports_lodging, parking_note, reservation_url, official_url, phone, popularity_score) VALUES ('00000000-0000-4000-a000-733134000000', 'kitaibaraki-iwaba-sauna', '北茨城 岩場サウナ', '磯の岩場に組んだ小屋サウナ。潮だまりで冷やす独特の体験ができる。', '茨城県', '北茨城市', '茨城県北茨城市（架空）', 36.8333, 140.75, 4600, 6800, null, 2, 5, 85, 97, '{"mon":{"open":"10:00","close":"18:00"},"tue":null,"wed":{"open":"10:00","close":"18:00"},"thu":{"open":"10:00","close":"18:00"},"fri":{"open":"10:00","close":"18:00"},"sat":{"open":"10:00","close":"18:00"},"sun":{"open":"10:00","close":"18:00"},"note":null}'::jsonb, null, true, false, null, null, 'https://example.com/kitaibaraki-iwaba', null, 0.44);
