INSERT INTO saunas (id, slug, name, description, prefecture, area, address, lat, lng, price_min, price_max, price_note, capacity_min, capacity_max, temp_min, temp_max, business_hours, closed_note, supports_day_trip, supports_lodging, parking_note, reservation_url, official_url, phone, popularity_score) VALUES ('00000000-0000-4000-a000-733136000000', 'chuzenji-kohan-roten', '中禅寺 湖畔露天サウナ', '標高1200mの湖畔。湖水は真夏でも冷たく、飛び込みができる桟橋がある。', '栃木県', '日光市', '栃木県日光市（架空）', 36.7333, 139.4833, 7500, 12000, null, 2, 10, 85, 98, '{"mon":{"open":"11:00","close":"20:00"},"tue":{"open":"11:00","close":"20:00"},"wed":{"open":"11:00","close":"20:00"},"thu":null,"fri":{"open":"11:00","close":"20:00"},"sat":{"open":"11:00","close":"20:00"},"sun":{"open":"11:00","close":"20:00"},"note":"冬季（12〜3月）は休業"}'::jsonb, null, true, true, '18台', 'https://example.com/chuzenji-roten/reserve', 'https://example.com/chuzenji-roten', null, 0.88);
INSERT INTO saunas (id, slug, name, description, prefecture, area, address, lat, lng, price_min, price_max, price_note, capacity_min, capacity_max, temp_min, temp_max, business_hours, closed_note, supports_day_trip, supports_lodging, parking_note, reservation_url, official_url, phone, popularity_score) VALUES ('00000000-0000-4000-a000-733137000000', 'shiobara-yusen-sauna', '塩原 湯泉サウナ', '温泉旅館に併設されたサウナ。渓流沿いだが入水はできず、地下水の水風呂を使う。', '栃木県', '那須塩原市', '栃木県那須塩原市（架空）', 36.95, 139.8, 3200, 4500, '日帰り入浴込み', 1, 12, 78, 88, '{"mon":{"open":"12:00","close":"21:00"},"tue":{"open":"12:00","close":"21:00"},"wed":{"open":"12:00","close":"21:00"},"thu":{"open":"12:00","close":"21:00"},"fri":{"open":"12:00","close":"21:00"},"sat":{"open":"12:00","close":"21:00"},"sun":{"open":"12:00","close":"21:00"},"note":null}'::jsonb, null, true, true, '30台', null, 'https://example.com/shiobara-yusen', null, 0.57);
